<?php
/**
 * ACC-008 address-edit confirmation follow-up; one controller only. PHP 8.0+; CLI only.
 * No DDL, bulk JSON rewrite or runner DB mutation. DB queries are read-only.
 * Owner must retain a fresh DB dump before --db-backup-confirmed apply.
 * Source rollback cannot restore data lost by subsequent application writes.
 * Dry run: php ACC-008_address-confirmation-r16_20261016.php --dry-run
 * Apply:   php ACC-008_address-confirmation-r16_20261016.php --db-backup-confirmed
 * Rollback (reupload runner first): --rollback=ACC-008_address-confirmation_<stamp>
 * Backups: ../_patch_backups/<printed name>/ outside public_html.
 */
if (PHP_SAPI !== 'cli') { http_response_code(403); exit; }
if (PHP_VERSION_ID < 80000) { fwrite(STDERR, "error=php_8_cli_required\n"); exit(1); }
const ACC008_PREFIX = 'ACC-008_address-confirmation_';
const ACC008_ADMISSION_B64 = '';
function acc008_log(string $key, string $value): void { echo $key . '=' . $value . "\n"; }
function acc008_fail(string $message): void { throw new RuntimeException($message); }
function acc008_path(string $root, string $relative): string {
    if (!preg_match('~^[A-Za-z0-9_./-]+$~D', $relative) || strpos($relative, '..') !== false || $relative[0] === '/') acc008_fail('unsafe_relative_path');
    $path = $root;
    foreach (explode('/', $relative) as $part) {
        $path .= '/' . $part;
        if (is_link($path)) acc008_fail('linked_path:' . $relative);
    }
    return $path;
}
function acc008_lint(string $path): void {
    if (!function_exists('proc_open')) acc008_fail('proc_open_unavailable');
    $descriptor = [0 => ['pipe', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']];
    $process = proc_open([PHP_BINARY, '-l', $path], $descriptor, $pipes);
    if (!is_resource($process)) acc008_fail('lint_launch_failed');
    fclose($pipes[0]);
    $out = stream_get_contents($pipes[1]); fclose($pipes[1]);
    $err = stream_get_contents($pipes[2]); fclose($pipes[2]);
    if (proc_close($process) !== 0) acc008_fail('php_lint_failed:' . basename($path));
}
function acc008_lint_payload(string $root, array $payload): void {
    if (!function_exists('proc_open')) acc008_fail('proc_open_unavailable');
    foreach ($payload as $relative => $row) {
        if (substr($relative, -4) !== '.php') continue;
        $temp = tempnam(sys_get_temp_dir(), 'acc008-lint-');
        if (!$temp) acc008_fail('host_lint_tempfile_failed');
        try {
            $resolved = realpath($temp);
            $rootPrefix = rtrim(str_replace('\\', '/', $root), '/') . '/';
            if (!$resolved || stripos(str_replace('\\', '/', $resolved), $rootPrefix) === 0) acc008_fail('host_lint_tempfile_inside_webroot');
            $content = base64_decode($row['content_b64'], true);
            if ($content === false || file_put_contents($temp, $content) !== strlen($content)) acc008_fail('host_lint_tempfile_write_failed');
            acc008_lint($temp);
            acc008_log('host_payload_lint', $relative . ':ok');
        } finally { if (is_file($temp) && !unlink($temp)) acc008_fail('host_lint_tempfile_cleanup_failed'); }
    }
}
function acc008_rows(mysqli $db, string $sql, int $cap = 128): array {
    $statement = $db->prepare($sql);
    if (!$statement) acc008_fail('read_only_metadata_query_failed');
    try {
        if (!$statement->execute()) acc008_fail('read_only_metadata_query_failed');
        $meta = $statement->result_metadata();
        if (!$meta) acc008_fail('metadata_result_missing');
        $bound = []; $refs = [];
        foreach ($meta->fetch_fields() as $column) { $bound[$column->name] = null; $refs[] = &$bound[$column->name]; }
        $meta->free();
        if (!$statement->bind_result(...$refs)) acc008_fail('metadata_bind_failed');
        $rows = [];
        while (($fetch = $statement->fetch()) === true) {
            $row = []; foreach ($bound as $key => $value) $row[$key] = $value;
            $rows[] = $row;
            if (count($rows) > $cap) acc008_fail('metadata_result_cap');
        }
        if ($fetch === false || $statement->errno) acc008_fail('metadata_fetch_failed');
        return $rows;
    } finally {
        $statement->close();
    }
}
/** ACC-008: narrow literal configuration grammar; never evaluate config code. */
function acc008_config_literals(string $code): array {
    if (!function_exists('token_get_all') || strlen($code) > 524288) acc008_fail('config_parser_unavailable_or_size_cap');
    $tokens = array_values(array_filter(token_get_all($code), static function($t) {
        return !is_array($t) || !in_array($t[0], [T_WHITESPACE,T_COMMENT,T_DOC_COMMENT], true);
    }));
    if (!isset($tokens[0]) || !is_array($tokens[0]) || $tokens[0][0] !== T_OPEN_TAG) acc008_fail('config_literal_grammar_required');
    $values = []; $count = count($tokens); $storedBytes=0;
    for ($i = 1; $i < $count;) {
        $t = $tokens[$i];
        if (is_array($t) && $t[0] === T_CLOSE_TAG && $i === $count - 1) break;
        if (!is_array($t) || !in_array(strtolower($t[1]), ['define','\\define'], true)
            || !in_array($t[0], [T_STRING,T_NAME_FULLY_QUALIFIED], true)
            || ($tokens[$i+1] ?? null) !== '(' || !is_array($tokens[$i+2] ?? null)
            || $tokens[$i+2][0] !== T_CONSTANT_ENCAPSED_STRING || ($tokens[$i+3] ?? null) !== ',') acc008_fail('config_literal_grammar_required');
        $name = acc008_config_string($tokens[$i+2][1]);
        if (!preg_match('/^[A-Z][A-Z0-9_]*$/D', $name) || array_key_exists($name, $values)) acc008_fail('config_duplicate_or_indirect_definition');
        $j=$i+4; $value='';
        while (true) {
            $operand=$tokens[$j]??null;
            if (!is_array($operand)) acc008_fail('config_literal_grammar_required');
            if ($operand[0]===T_CONSTANT_ENCAPSED_STRING) $piece=acc008_config_string($operand[1]);
            elseif ($operand[0]===T_LNUMBER && preg_match('/^(?:0|[1-9][0-9]*)$/D',$operand[1])) $piece=$operand[1];
            elseif ($operand[0]===T_STRING && array_key_exists($operand[1],$values)) $piece=$values[$operand[1]];
            else acc008_fail('config_unknown_or_unsafe_operand');
            if (strlen($value)+strlen($piece)>524288) acc008_fail('config_evaluated_value_size_cap');
            $value.=$piece; $j++;
            if (($tokens[$j]??null)==='.') { $j++; continue; }
            if (($tokens[$j]??null)!==')'||($tokens[$j+1]??null)!==';') acc008_fail('config_literal_grammar_required');
            break;
        }
        $storedBytes+=strlen($value);
        if ($storedBytes>2097152) acc008_fail('config_aggregate_value_size_cap');
        $values[$name]=$value; $i=$j+2;
    }
    return $values;
}
function acc008_config_string(string $literal): string {
    if (strlen($literal)<2 || !in_array($literal[0],["'",'"'],true) || substr($literal,-1)!==$literal[0]) acc008_fail('config_binary_or_invalid_string_literal');
    $value = substr($literal, 1, -1);
    if ($literal[0] === "'") return str_replace(["\\'",'\\\\'], ["'",'\\'], $value);
    // Double-quoted strings with escapes/interpolation require explicit review.
    if (strpos($value, '\\') !== false || strpos($value, '$') !== false) acc008_fail('config_escaped_double_quote_requires_review');
    return $value;
}
function acc008_config_targets(string $root): array {
    $configs = [];
    foreach (['catalog'=>'config.php','admin'=>'adminEvhenii/config.php'] as $app=>$relative) {
        $path = acc008_path($root, $relative);
        if (!is_file($path) || filesize($path)>524288) acc008_fail('hosting_config_missing_or_size_cap');
        $body = file_get_contents($path); if (!is_string($body)) acc008_fail('hosting_config_read_failed');
        $v = acc008_config_literals($body); unset($body);
        foreach (['DB_HOSTNAME','DB_PORT','DB_DATABASE','DB_PREFIX','DB_DRIVER','DB_USERNAME','DB_PASSWORD','DIR_OPENCART','DIR_APPLICATION','DIR_SYSTEM','DIR_EXTENSION','DIR_CONFIG','DIR_TEMPLATE','DIR_CACHE','APPLICATION'] as $key) {
            if (!array_key_exists($key,$v)) acc008_fail('hosting_config_incomplete:'.$app);
        }
        if ($v['APPLICATION']!==($app==='admin'?'Admin':'Catalog')) acc008_fail('application_identity_changed:'.$app);
        if ($v['DB_DRIVER']!=='mysqli' || stripos($v['DB_HOSTNAME'],'p:')===0
            || !preg_match('/^[1-9][0-9]{0,4}$/D',$v['DB_PORT']) || (int)$v['DB_PORT']>65535
            || !preg_match('/^[A-Za-z0-9_]+$/D',$v['DB_PREFIX'])) acc008_fail('unsupported_or_persistent_db_target:'.$app);
        foreach (['DIR_OPENCART'=>'','DIR_APPLICATION'=>($app==='admin'?'adminEvhenii':'catalog'),'DIR_SYSTEM'=>'system','DIR_EXTENSION'=>'extension','DIR_CONFIG'=>'system/config','DIR_TEMPLATE'=>($app==='admin'?'adminEvhenii':'catalog').'/view/template'] as $key=>$expected) {
            $actual = realpath($v[$key]); $wanted = $expected===''?realpath($root):realpath(acc008_path($root,$expected));
            if ($actual===false || $wanted===false || $actual!==$wanted) acc008_fail('runtime_path_mapping_changed:'.$app.'/'.$key);
        }
        $configs[$app]=$v;
    }
    foreach(['catalog'=>'cache_dir_config_relative','admin'=>'admin_cache_dir_config_relative']as$app=>$label){
        $cache=realpath($configs[$app]['DIR_CACHE']);
        if ($cache===false||!is_dir($cache)) acc008_fail('configured_cache_directory_missing:'.$app);
        $from=explode('/',trim(str_replace('\\','/',$root),'/'));$to=explode('/',trim(str_replace('\\','/',$cache),'/'));$common=0;
        while(isset($from[$common],$to[$common])&&$from[$common]===$to[$common])$common++;
        acc008_log($label,str_repeat('../',count($from)-$common).implode('/',array_slice($to,$common)));
    }
    foreach (['DB_HOSTNAME','DB_PORT','DB_DATABASE','DB_PREFIX','DB_DRIVER'] as $key) {
        if ($configs['catalog'][$key]!==$configs['admin'][$key]) acc008_fail('catalog_admin_db_target_mismatch');
    }
    acc008_log('config_admission','literal_nonpersistent_same_target_and_paths');
    return $configs['catalog'];
}
function acc008_admission(): array {
    return json_decode(base64_decode(ACC008_ADMISSION_B64,true),true,512,JSON_THROW_ON_ERROR);
}
function acc008_events_normalized(array $rows): array {
    $result=[];
    foreach($rows as $r) $result[]=['code'=>(string)$r['code'],'trigger'=>(string)$r['trigger'],'action'=>(string)$r['action'],'sort_order'=>(int)$r['sort_order'],'status'=>(string)($r['status']??1)];
    usort($result,static function($a,$b){return [$a['sort_order'],$a['code'],$a['trigger'],$a['action'],$a['status']]<=>[$b['sort_order'],$b['code'],$b['trigger'],$b['action'],$b['status']];});
    return $result;
}
function acc008_runtime_files(string $root,array $payload): void {
    clearstatcache(true);
    $admission=acc008_admission();
    foreach($admission['source_identities'] as $relative=>$expected) {
        $path=acc008_path($root,$relative);
        $allowed=isset($payload[$relative])?[$expected,$payload[$relative]['after_sha256']]:[$expected];
        if(!is_file($path)||!in_array(hash_file('sha256',$path),$allowed,true)) acc008_fail('runtime_source_changed:'.$relative);
    }
    // Actual namespace/view handlers can select extension/ocmod code. Refuse
    // any generated PHP/Twig there, including paths outside the 51 candidates.
    $ocmod=acc008_path($root,'extension/ocmod');
    if(file_exists($ocmod)) {
        if(!is_dir($ocmod)) acc008_fail('ocmod_tree_unreadable');
        // Iterator open/read failures throw before writes; do not infer directory
        // enumeration support from the platform-dependent is_readable flag.
        $iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($ocmod,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);
        $seen=0;
        foreach($iterator as $file) {
            if(++$seen>2048) acc008_fail('ocmod_inventory_cap');
            if($file->isLink()) acc008_fail('linked_ocmod_entry');
            if($file->isFile()&&preg_match('/\.(?:php|twig)$/iD',$file->getFilename())) acc008_fail('generated_ocmod_requires_review');
        }
    }
    acc008_log('runtime_sources','exact_reviewed_sources_and_no_generated_ocmod');
}
function acc008_backup_path(string $root,string $name): string {
    $parent=realpath(dirname($root));
    if(!$parent||$parent===$root) acc008_fail('private_backup_parent_unavailable');
    // Apply mkdir proves write access before any source write. Rollback only
    // reads these backups and must not require a writable parent directory.
    $parent=str_replace('\\','/',$parent);
    return acc008_path($parent,'_patch_backups/'.$name);
}

function acc008_preflight(string $root): void {
    $config = acc008_config_targets($root);
    if (!class_exists('mysqli')) acc008_fail('mysqli_required');
    $prefix = $config['DB_PREFIX'];
    mysqli_report(MYSQLI_REPORT_OFF);
    $db = @new mysqli($config['DB_HOSTNAME'], $config['DB_USERNAME'], $config['DB_PASSWORD'], $config['DB_DATABASE'], (int)$config['DB_PORT']);
    unset($config);
    if ($db->connect_errno || !$db->set_charset('utf8mb4')) acc008_fail('db_connection_or_charset_failed');
    try {
        foreach (['customer'=>'customer_id', 'address'=>'address_id','customer_activity'=>null,'session'=>null,'customer_login'=>null] as $table => $primary) {
            $name = $prefix . $table;
            $engine = acc008_rows($db, "SELECT ENGINE AS engine FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = '" . $db->real_escape_string($name) . "'");
            if (count($engine) !== 1 || strcasecmp((string)$engine[0]['engine'], 'InnoDB') !== 0) acc008_fail('transactional_engine_required:' . $table);
            if ($primary === null) continue;
            $columns = acc008_rows($db, "SELECT COLUMN_NAME AS field, DATA_TYPE AS type FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = '" . $db->real_escape_string($name) . "'");
            $map = array_column($columns, 'type', 'field');
            if (!isset($map['custom_field']) || !preg_match('/^(?:long|medium)?text$/iD', $map['custom_field'])) acc008_fail('custom_field_schema_changed:' . $table);
            $indexes = acc008_rows($db, "SELECT COLUMN_NAME AS field FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = '" . $db->real_escape_string($name) . "' AND INDEX_NAME = 'PRIMARY' ORDER BY SEQ_IN_INDEX");
            if (count($indexes) !== 1 || $indexes[0]['field'] !== $primary) acc008_fail('primary_key_changed:' . $table);
        }
        $fields = acc008_rows($db, 'SELECT custom_field_id, location, type, status FROM `' . $prefix . 'custom_field` ORDER BY custom_field_id', 128);
        $groups = acc008_rows($db, 'SELECT custom_field_id, customer_group_id, `required` FROM `' . $prefix . 'custom_field_customer_group` ORDER BY custom_field_id, customer_group_id', 256);
        foreach (['theme'=>['route','store_id','code','status'], 'event'=>['code','trigger','action','status','sort_order'],'startup'=>['code','action','status','sort_order']] as $table => $requiredColumns) {
            $columns = acc008_rows($db, "SELECT COLUMN_NAME AS field FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = '" . $db->real_escape_string($prefix . $table) . "'");
            foreach ($requiredColumns as $column) if (!in_array($column, array_column($columns, 'field'), true)) acc008_fail('metadata_schema_requires_review:' . $table . '/' . $column);
        }
        // The actual Event::trigger matches prefixes even without a wildcard.
        // Return every active identity for review; no SQL substring classifier.
        // Admin registers PHP-truthy statuses from all raw event rows. A status=1
        // SQL filter misses e.g. status 2/-1. Inventory disabled rows too, cap all.
        $eventRows = acc008_rows($db, 'SELECT code, `trigger`, action, status, sort_order FROM `' . $prefix . 'event` ORDER BY sort_order, code, `trigger`, action LIMIT 513',512);
        $events = array_values(array_filter($eventRows,static function($r){return (bool)$r['status'];}));
        acc008_log('event_rows_scanned',(string)count($eventRows));
        $startupRows = acc008_rows($db, 'SELECT code, action, status, sort_order FROM `' . $prefix . 'startup` ORDER BY sort_order, code, action LIMIT 65',64);
        // Admin uses PHP truthiness, not SQL status=1; include nonzero legacy
        // statuses conservatively. Even the raw disabled inventory is capped.
        $startups = array_values(array_filter($startupRows,static function($r){return (bool)$r['status'];}));
        acc008_log('active_startups',json_encode($startups,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));
        // DB startup controllers can register handlers outside the event table.
        // No unknown startup is admitted; return its identities for review.
        $allThemes = acc008_rows($db, 'SELECT route, store_id, status FROM `' . $prefix . 'theme` WHERE status = 1 ORDER BY store_id, route LIMIT 257', 256);
        $themes = array_values(array_filter($allThemes,static function($r){return preg_match('~(?:^|/)(?:account/edit|account/address_form|customer/customer_form|customer/address_form)(?:\.twig)?$~D',(string)$r['route']);}));
        acc008_log('metadata', json_encode(['custom_fields'=>$fields, 'custom_field_groups'=>$groups, 'event_inventory_scope'=>'all_php_truthy_active_raw_inventory_capped', 'active_events'=>$events, 'active_startups'=>$startups, 'relevant_theme_overrides'=>$themes], JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR));
        $admission=acc008_admission();
        if ($startups) acc008_fail('active_startup_requires_independent_review');
        if ($themes) acc008_fail('active_theme_override_requires_review');
        if (acc008_events_normalized($events)!==acc008_events_normalized($admission['active_events'])) acc008_fail('active_event_inventory_changed');
        foreach ($fields as &$row) { $row['custom_field_id']=(int)$row['custom_field_id']; $row['status']=(int)$row['status']; } unset($row);
        foreach ($groups as &$row) { foreach(['custom_field_id','customer_group_id','required'] as $key) $row[$key]=(int)$row[$key]; } unset($row);
        if ($fields!==$admission['custom_fields'] || $groups!==$admission['custom_field_groups']) acc008_fail('custom_field_metadata_changed');
        acc008_log('db_preflight', 'read_only_ok');
    } finally { $db->close(); }
}
function acc008_restore(string $root, string $backup, array $rows): void {
    foreach (array_reverse($rows, true) as $relative => $row) {
        $target = acc008_path($root, $relative);
        if ($row['new']) {
            if (is_file($target) && !unlink($target)) acc008_fail('remove_new_file_failed:' . $relative);
        } else {
            $source = acc008_path($backup, $relative);
            if (!is_file($source) || hash_file('sha256', $source) !== $row['before_sha256'] || !copy($source, $target)) acc008_fail('restore_failed:' . $relative);
        }
    }
}
