            $temp = tempnam(dirname($target), '.acc008-');
            if (!$temp) acc008_fail('temporary_file_failed');
            try {
                $content = base64_decode($row['content_b64'], true);
                if (file_put_contents($temp, $content) !== strlen($content)) acc008_fail('staged_write_failed');
                if (substr($relative, -4) === '.php') acc008_lint($temp);
                if ($row['new'] ? file_exists($target) : (!is_file($target) || hash_file('sha256', $target) !== $row['before_sha256'])) acc008_fail('source_changed_during_apply:' . $relative);
                if (!chmod($temp, $row['new'] ? 0644 : (fileperms($target) & 0777))) acc008_fail('file_mode_failed');
                if (!rename($temp, $target)) acc008_fail('atomic_replace_failed:' . $relative);
                $written[$relative] = $row;
                if (substr($relative, -4) === '.php') { acc008_lint($target); acc008_log('php_lint', $relative . ':ok'); }
                acc008_log('changed_file', $relative);
            } finally { if (is_file($temp)) unlink($temp); }
        }
    } catch (Throwable $e) {
        acc008_restore($root, $backup, $written);
        acc008_log('restore_on_fail', 'ok');
        throw $e;
    }
    acc008_log('files_changed', (string)count($written)); acc008_log('done', 'ok'); @unlink(__FILE__);
} catch (Throwable $e) { fwrite(STDERR, 'error=' . $e->getMessage() . "\n"); exit(1); }
